<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Dashboard extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->helper('xssclean');        $this->load->library('email');        $this->load->helper('email');        fnIfCheckUserLoggedIn();    }    public function index() {        $this->load->model("commonmodel");        $ArrProfileInfo   = fnGetUserLoggedInfo(1);        $VarRemainingUser = $this->commonmodel->remaininguseravailable($ArrProfileInfo['companyid'], 1);        if ($VarRemainingUser == 0) {            //die('User Limit Ended. Can\'t add more users');        }        if (empty($ArrProfileInfo)) {            redirect(base_url());        } else {            $this->load->view('management/mgmtdashboard');        }    }}